    private const int MaxPageSize=100;
    private static readonly string[] AfterServiceStates=["RECEIVED","PROVIDER_CONFIRMED","VISIT_SCHEDULED","IN_PROGRESS","RESOLVED","UNRESOLVED_CLOSED","CONVERTED_TO_DISPUTE"];
    private static readonly string[] DisputeStates=["OPEN","UNDER_REVIEW","WAITING_CUSTOMER","WAITING_PROVIDER","RESOLVED","CLOSED"];
    private static readonly string[] EvidenceSources=["REQUEST","QUOTE","QUOTE_REVISION","TRANSACTION_SNAPSHOT","COMPLETION_EVIDENCE","AFTER_SERVICE_EVIDENCE","VISIT","CHAT","WALLET_FEE","OTHER"];

    public async Task<AdminAfterServiceListResponse> SearchAfterServicesAsync(string? search,string? status,bool? withinWarranty,bool? providerUnconfirmed,bool? visitScheduled,bool? inProgress,bool? convertedToDispute,DateOnly? receivedFrom,DateOnly? receivedTo,int page,int pageSize,CancellationToken token)
    {
        ValidatePage(page,pageSize); var query=from item in db.AfterServiceCases.AsNoTracking() join tx in db.Transactions.AsNoTracking() on item.TransactionId equals tx.Id join category in db.ServiceCategories.AsNoTracking() on tx.CategoryId equals category.Id join customer in db.CustomerProfiles.AsNoTracking() on item.CustomerProfileId equals customer.Id join customerUser in db.Users.AsNoTracking() on customer.UserId equals customerUser.Id join provider in db.ProviderProfiles.AsNoTracking() on item.ProviderProfileId equals provider.Id join providerUser in db.Users.AsNoTracking() on provider.UserId equals providerUser.Id select new{Item=item,Tx=tx,Category=category,Customer=customer,CustomerUser=customerUser,Provider=provider,ProviderUser=providerUser};
        var term=Clean(search); if(term is not null) query=Guid.TryParse(term,out var id)?query.Where(x=>x.Item.PublicId==id||x.Tx.PublicId==id):query.Where(x=>x.Item.Subject.Contains(term)||x.Category.Name.Contains(term)||x.Customer.DisplayName.Contains(term)||x.Provider.BusinessName.Contains(term));
        if(Clean(status) is { } state) query=query.Where(x=>x.Item.StatusCode==state.ToUpper()); if(withinWarranty.HasValue) query=query.Where(x=>x.Item.IsWithinWarranty==withinWarranty); if(providerUnconfirmed==true) query=query.Where(x=>x.Item.ProviderConfirmedAt==null); if(visitScheduled==true) query=query.Where(x=>x.Item.StatusCode=="VISIT_SCHEDULED"); if(inProgress==true) query=query.Where(x=>x.Item.StatusCode=="IN_PROGRESS"); if(convertedToDispute==true) query=query.Where(x=>x.Item.StatusCode=="CONVERTED_TO_DISPUTE"); if(receivedFrom.HasValue)query=query.Where(x=>x.Item.ReceivedAt>=receivedFrom.Value.ToDateTime(TimeOnly.MinValue));if(receivedTo.HasValue)query=query.Where(x=>x.Item.ReceivedAt<receivedTo.Value.AddDays(1).ToDateTime(TimeOnly.MinValue));
        var total=await query.CountAsync(token); var rows=await query.OrderByDescending(x=>x.Item.ReceivedAt).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(token); var adminIds=rows.Where(x=>x.Item.AssignedAdminUserId.HasValue).Select(x=>x.Item.AssignedAdminUserId!.Value).Distinct().ToArray(); var admins=await db.Users.AsNoTracking().Where(x=>adminIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.LoginId,token);var caseIds=rows.Select(x=>x.Item.Id).ToArray();var disputedIds=await db.DisputeCases.AsNoTracking().Where(x=>x.AfterServiceCaseId.HasValue&&caseIds.Contains(x.AfterServiceCaseId.Value)).Select(x=>x.AfterServiceCaseId!.Value).ToHashSetAsync(token);
        return new(total,page,pageSize,rows.Select(x=>new AdminAfterServiceListItem(x.Item.PublicId,AsNumber(x.Item.PublicId),x.Tx.PublicId,TxNumber(x.Tx.PublicId),x.Category.Name,x.Customer.DisplayName,Mask(x.CustomerUser.Phone),x.Provider.BusinessName,Mask(x.ProviderUser.Phone),x.Item.IsWithinWarranty,x.Item.WarrantyEndDate,x.Item.ReceivedAt,x.Item.StatusCode,x.Item.LastActionAt,x.Item.AssignedAdminUserId.HasValue&&admins.TryGetValue(x.Item.AssignedAdminUserId.Value,out var admin)?admin:null,x.Item.DueAt,disputedIds.Contains(x.Item.Id))).ToArray());
    }

    public async Task<AdminAfterServiceDetail?> GetAfterServiceAsync(Guid id,CancellationToken token){var item=await db.AfterServiceCases.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==id,token);return item is null?null:await BuildAfterServiceAsync(item,token);}

    public async Task<AdminAfterServiceDetail> CreateAfterServiceAsync(CreateAfterServiceRequest request,Guid actorId,CancellationToken token)
    {
        ValidateRequired(request.Subject,"A/S 제목을 입력해 주세요.");ValidateRequired(request.SymptomDescription,"증상을 입력해 주세요.");var actor=await ActorAsync(actorId,token);var existing=await db.AfterServiceCases.AsNoTracking().SingleOrDefaultAsync(x=>x.IdempotencyKey==request.IdempotencyKey,token);if(existing is not null)return await BuildAfterServiceAsync(existing,token);var row=await TransactionAsync(request.TransactionId,token);if(!row.Transaction.CompletedAt.HasValue)throw Error("AFTER_SERVICE_TRANSACTION_NOT_COMPLETED","작업 완료된 거래만 A/S를 접수할 수 있습니다.",409);await using var transaction=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(token):null;var reporter=Reporter(request.ReporterRoleCode,row);var now=DateTime.UtcNow;var start=DateOnly.FromDateTime(row.Transaction.CompletedAt.Value);var end=start.AddDays(row.Transaction.WarrantyDaysSnapshot);var received=DateOnly.FromDateTime(now);var item=new AfterServiceCase{TransactionId=row.Transaction.Id,CustomerProfileId=row.Transaction.CustomerProfileId,ProviderProfileId=row.Transaction.ProviderProfileId,ReportedByUserId=reporter,StatusCode="RECEIVED",Subject=request.Subject.Trim(),Description=request.SymptomDescription.Trim(),RequestDetails=Clean(request.RequestDetails),ReceivedAt=now,WarrantyStartDate=start,WarrantyEndDate=end,IsWithinWarranty=received>=start&&received<=end,LastActionAt=now,IdempotencyKey=request.IdempotencyKey.Trim(),CreatedAt=now,CreatedByUserId=actor,UpdatedAt=now,UpdatedByUserId=actor};db.AfterServiceCases.Add(item);await db.SaveChangesAsync(token);db.AfterServiceActions.Add(NewAfterAction(item,null,"RECEIVED","RECEIVED",request.SymptomDescription,null,actor,request.IdempotencyKey,now));await EnsureServiceHistoryAsync(item,row,"AFTER_SERVICE_RECEIVED","A/S 접수",request.SymptomDescription,actor,now,token);Audit(actor,"AFTER_SERVICE_RECEIVED","AFTER_SERVICE_CASE",item.PublicId,null,Snap(item),null,now);Outbox("AfterServiceCase",item.PublicId,"AFTER_SERVICE_RECEIVED",new{afterServiceId=item.PublicId,transactionId=row.Transaction.PublicId,status=item.StatusCode},actor,now);await db.SaveChangesAsync(token);if(transaction is not null)await transaction.CommitAsync(token);return await BuildAfterServiceAsync(item,token);
    }

    public async Task<AdminAfterServiceDetail> ChangeAfterServiceStatusAsync(Guid id,ChangeAfterServiceStatusRequest request,Guid actorId,CancellationToken token)
    {
        var actor=await ActorAsync(actorId,token);var item=await AfterServiceAsync(id,token);var existing=await db.AfterServiceActions.AsNoTracking().AnyAsync(x=>x.IdempotencyKey==request.IdempotencyKey,token);if(existing)return await BuildAfterServiceAsync(item,token);var target=Code(request.TargetStatusCode);if(!AfterServiceStates.Contains(target)||target=="CONVERTED_TO_DISPUTE")throw Error("AFTER_SERVICE_STATUS_INVALID","A/S 상태를 확인해 주세요.");var overrideReason=Clean(request.AdminOverrideReason);var valid=ValidAfterTransition(item.StatusCode,target,item.VisitRequired);if(!valid&&overrideReason is null)throw Error("AFTER_SERVICE_TRANSITION_INVALID",$"{item.StatusCode} 상태에서 {target} 상태로 변경할 수 없습니다.",409);if(IsAfterTerminal(item.StatusCode))throw Error("AFTER_SERVICE_ALREADY_CLOSED","종료된 A/S 상태는 변경할 수 없습니다.",409);var now=DateTime.UtcNow;var before=Snap(item);var actionType=overrideReason is not null?"ADMIN_OVERRIDE":"STATE_CHANGE";
        if(target=="PROVIDER_CONFIRMED"){if(Clean(request.ProviderResponse) is null||!request.VisitRequired.HasValue)throw Error("PROVIDER_CONFIRMATION_REQUIRED","전문가 응답과 방문 필요 여부를 입력해 주세요.");item.ProviderConfirmedAt=now;item.ProviderResponseText=request.ProviderResponse!.Trim();item.VisitRequired=request.VisitRequired;actionType="PROVIDER_CONFIRMATION";}
        if(target=="VISIT_SCHEDULED"){if(!request.ScheduledAt.HasValue)throw Error("VISIT_SCHEDULE_REQUIRED","방문 예정일시를 입력해 주세요.");actionType="VISIT_SCHEDULED";}
        if(target=="IN_PROGRESS"){item.StartedAt??=now;}
        if(target=="RESOLVED"){if(Clean(request.ResolutionSummary) is null)throw Error("AFTER_SERVICE_RESOLUTION_REQUIRED","최종 조치와 처리결과를 입력해 주세요.");item.ResolutionSummary=request.ResolutionSummary!.Trim();item.RecurrenceOccurred=request.RecurrenceOccurred;item.CompletedAt=now;actionType="RESOLUTION";}
        if(target=="UNRESOLVED_CLOSED"){if(Clean(request.UnresolvedReason) is null)throw Error("AFTER_SERVICE_UNRESOLVED_REASON_REQUIRED","미해결 종료 사유를 입력해 주세요.");item.UnresolvedReason=request.UnresolvedReason!.Trim();item.CompletedAt=now;actionType="UNRESOLVED_CLOSURE";}
        var from=item.StatusCode;item.StatusCode=target;item.LastActionAt=now;item.UpdatedAt=now;item.UpdatedByUserId=actor;db.AfterServiceActions.Add(NewAfterAction(item,from,target,actionType,request.Note,overrideReason,actor,request.IdempotencyKey,now,request.ScheduledAt));var tx=await TransactionAsyncById(item.TransactionId,token);if(target=="IN_PROGRESS")await EnsureServiceHistoryAsync(item,tx,"AFTER_SERVICE_STARTED","A/S 처리 시작",request.Note??"A/S 처리를 시작했습니다.",actor,now,token);if(target=="RESOLVED")await EnsureServiceHistoryAsync(item,tx,"AFTER_SERVICE_COMPLETED","A/S 해결",item.ResolutionSummary!,actor,now,token);Audit(actor,$"AFTER_SERVICE_{target}","AFTER_SERVICE_CASE",item.PublicId,before,Snap(item),overrideReason??request.Note,now);Outbox("AfterServiceCase",item.PublicId,$"AFTER_SERVICE_{target}",new{afterServiceId=item.PublicId,transactionId=tx.Transaction.PublicId,status=target},actor,now);await db.SaveChangesAsync(token);return await BuildAfterServiceAsync(item,token);
    }

    public async Task<AdminAfterServiceDetail> AddAfterServiceActionAsync(Guid id,AddAfterServiceActionRequest request,Guid actorId,CancellationToken token)
    {
        var actor=await ActorAsync(actorId,token);var item=await AfterServiceAsync(id,token);if(IsAfterTerminal(item.StatusCode))throw Error("AFTER_SERVICE_ALREADY_CLOSED","종료된 A/S에는 조치를 추가할 수 없습니다.",409);var type=Code(request.ActionTypeCode);if(type is not("VISIT" or "REVISIT" or "TREATMENT"))throw Error("AFTER_SERVICE_ACTION_TYPE_INVALID","방문, 재방문 또는 조치 유형만 등록할 수 있습니다.");if(await db.AfterServiceActions.AsNoTracking().AnyAsync(x=>x.IdempotencyKey==request.IdempotencyKey,token))return await BuildAfterServiceAsync(item,token);if(type is "VISIT" or "REVISIT"&&(!request.PerformedAt.HasValue||!request.VisitOccurred))throw Error("AFTER_SERVICE_VISIT_REQUIRED","방문일시와 방문 여부를 입력해 주세요.");if(type=="TREATMENT"&&Clean(request.ResultText) is null)throw Error("AFTER_SERVICE_RESULT_REQUIRED","조치 결과를 입력해 주세요.");var now=DateTime.UtcNow;db.AfterServiceActions.Add(new AfterServiceAction{AfterServiceCaseId=item.Id,FromStatusCode=item.StatusCode,ToStatusCode=item.StatusCode,ActionTypeCode=type,ActionNote=Clean(request.ActionNote),ScheduledAt=request.ScheduledAt?.ToUniversalTime(),PerformedAt=request.PerformedAt?.ToUniversalTime(),ProviderProfileId=item.ProviderProfileId,VisitOccurred=request.VisitOccurred,MaterialsText=Clean(request.MaterialsText),ResultText=Clean(request.ResultText),RecurrenceOccurred=request.RecurrenceOccurred,OccurredAt=now,ActorUserId=actor,IdempotencyKey=request.IdempotencyKey.Trim()});item.LastActionAt=now;item.RecurrenceOccurred=request.RecurrenceOccurred??item.RecurrenceOccurred;item.UpdatedAt=now;item.UpdatedByUserId=actor;Audit(actor,"AFTER_SERVICE_ACTION_ADDED","AFTER_SERVICE_CASE",item.PublicId,null,JsonSerializer.Serialize(request),request.ActionNote,now);Outbox("AfterServiceCase",item.PublicId,type=="REVISIT"?"AFTER_SERVICE_REVISIT":"AFTER_SERVICE_ACTION_ADDED",new{afterServiceId=item.PublicId,actionType=type},actor,now);await db.SaveChangesAsync(token);return await BuildAfterServiceAsync(item,token);
    }

    public async Task<AdminAfterServiceDetail> AddAfterServiceFileAsync(Guid id,AddAfterServiceFileRequest request,Guid actorId,CancellationToken token)
    {var actor=await ActorAsync(actorId,token);var item=await AfterServiceAsync(id,token);var file=await db.Files.SingleOrDefaultAsync(x=>x.PublicId==request.FileId&&x.StatusCode=="ACTIVE",token)??throw Error("FILE_NOT_FOUND","사용할 수 있는 파일을 찾을 수 없습니다.",404);if(!await FileBelongsToTransactionAsync(file.Id,item.TransactionId,token))throw Error("EVIDENCE_FILE_SCOPE_INVALID","해당 거래와 연결된 파일만 증빙으로 등록할 수 있습니다.",403);if(!await db.AfterServiceFiles.AnyAsync(x=>x.AfterServiceCaseId==item.Id&&x.FileId==file.Id,token))db.AfterServiceFiles.Add(new AfterServiceFile{AfterServiceCaseId=item.Id,FileId=file.Id,RoleCode=Clean(request.RoleCode)?.ToUpperInvariant(),Description=Clean(request.Description),CreatedAt=DateTime.UtcNow,CreatedByUserId=actor});Audit(actor,"AFTER_SERVICE_EVIDENCE_ADDED","AFTER_SERVICE_CASE",item.PublicId,null,JsonSerializer.Serialize(new{request.FileId,request.RoleCode}),request.Description,DateTime.UtcNow);await db.SaveChangesAsync(token);return await BuildAfterServiceAsync(item,token);}

    public async Task<AdminDisputeDetail> ConvertToDisputeAsync(Guid id,ConvertAfterServiceToDisputeRequest request,Guid actorId,CancellationToken token)
    {
        var actor=await ActorAsync(actorId,token);var item=await AfterServiceAsync(id,token);var existing=await db.DisputeCases.SingleOrDefaultAsync(x=>x.AfterServiceCaseId==item.Id,token);if(existing is not null)throw Error("AFTER_SERVICE_DISPUTE_DUPLICATED","이미 분쟁으로 전환된 A/S입니다.",409);if(IsAfterTerminal(item.StatusCode))throw Error("AFTER_SERVICE_ALREADY_CLOSED","종료된 A/S는 분쟁으로 전환할 수 없습니다.",409);var row=await TransactionAsyncById(item.TransactionId,token);await using var transaction=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(token):null;var dispute=await CreateDisputeEntityAsync(row,item,ReporterUser(item,row),request.Subject,request.Reason,request.IdempotencyKey,actor,token);var now=DateTime.UtcNow;var from=item.StatusCode;item.StatusCode="CONVERTED_TO_DISPUTE";item.ConvertedToDisputeAt=now;item.CompletedAt=now;item.LastActionAt=now;item.UpdatedAt=now;item.UpdatedByUserId=actor;db.AfterServiceActions.Add(NewAfterAction(item,from,item.StatusCode,"DISPUTE_CONVERSION",request.Reason,request.Reason,actor,$"as:{request.IdempotencyKey}",now));Audit(actor,"AFTER_SERVICE_CONVERTED_TO_DISPUTE","AFTER_SERVICE_CASE",item.PublicId,null,Snap(item),request.Reason,now);Outbox("AfterServiceCase",item.PublicId,"AFTER_SERVICE_CONVERTED_TO_DISPUTE",new{afterServiceId=item.PublicId,disputeId=dispute.PublicId},actor,now);await db.SaveChangesAsync(token);if(transaction is not null)await transaction.CommitAsync(token);return await BuildDisputeAsync(dispute,token);
    }

    public async Task<AdminDisputeListResponse> SearchDisputesAsync(string? search,string? status,Guid? assignedAdminId,bool? hasAfterService,DateOnly? receivedFrom,DateOnly? receivedTo,bool? unresolved,int page,int pageSize,CancellationToken token)
    {
        ValidatePage(page,pageSize);var query=from item in db.DisputeCases.AsNoTracking()join tx in db.Transactions.AsNoTracking()on item.TransactionId equals tx.Id join customer in db.CustomerProfiles.AsNoTracking()on tx.CustomerProfileId equals customer.Id join cu in db.Users.AsNoTracking()on customer.UserId equals cu.Id join provider in db.ProviderProfiles.AsNoTracking()on tx.ProviderProfileId equals provider.Id join pu in db.Users.AsNoTracking()on provider.UserId equals pu.Id select new{Item=item,Tx=tx,Customer=customer,CU=cu,Provider=provider,PU=pu};var term=Clean(search);if(term is not null)query=Guid.TryParse(term,out var id)?query.Where(x=>x.Item.PublicId==id||x.Tx.PublicId==id):query.Where(x=>x.Item.Subject.Contains(term)||x.Customer.DisplayName.Contains(term)||x.Provider.BusinessName.Contains(term));if(Clean(status)is{} state)query=query.Where(x=>x.Item.StatusCode==state.ToUpper());if(assignedAdminId.HasValue){var admin=await db.Users.AsNoTracking().Where(x=>x.PublicId==assignedAdminId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);query=query.Where(x=>x.Item.AssignedAdminUserId==admin);}if(hasAfterService.HasValue)query=query.Where(x=>x.Item.AfterServiceCaseId.HasValue==hasAfterService);if(receivedFrom.HasValue)query=query.Where(x=>x.Item.ReceivedAt>=receivedFrom.Value.ToDateTime(TimeOnly.MinValue));if(receivedTo.HasValue)query=query.Where(x=>x.Item.ReceivedAt<receivedTo.Value.AddDays(1).ToDateTime(TimeOnly.MinValue));if(unresolved==true)query=query.Where(x=>x.Item.StatusCode!="RESOLVED"&&x.Item.StatusCode!="CLOSED");var total=await query.CountAsync(token);var rows=await query.OrderBy(x=>x.Item.DueAt==null).ThenBy(x=>x.Item.DueAt).ThenBy(x=>x.Item.ReceivedAt).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(token);var ids=rows.Where(x=>x.Item.AssignedAdminUserId.HasValue).Select(x=>x.Item.AssignedAdminUserId!.Value).Distinct().ToArray();var admins=await db.Users.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.LoginId,token);return new(total,page,pageSize,rows.Select(x=>new AdminDisputeListItem(x.Item.PublicId,DisputeNumber(x.Item.PublicId),x.Tx.PublicId,TxNumber(x.Tx.PublicId),x.Item.Subject,x.Customer.DisplayName,Mask(x.CU.Phone),x.Provider.BusinessName,Mask(x.PU.Phone),x.Item.StatusCode,x.Item.AssignedAdminUserId.HasValue&&admins.TryGetValue(x.Item.AssignedAdminUserId.Value,out var name)?name:null,x.Item.ReceivedAt,x.Item.DueAt,x.Item.LastActionAt,x.Item.AfterServiceCaseId.HasValue)).ToArray());
    }

    public async Task<AdminDisputeDetail?> GetDisputeAsync(Guid id,CancellationToken token){var item=await db.DisputeCases.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==id,token);return item is null?null:await BuildDisputeAsync(item,token);}
    public async Task<AdminDisputeDetail> CreateDisputeAsync(CreateDisputeRequest request,Guid actorId,CancellationToken token){ValidateRequired(request.Subject,"분쟁 제목을 입력해 주세요.");ValidateRequired(request.Description,"분쟁 내용을 입력해 주세요.");var actor=await ActorAsync(actorId,token);var existing=await db.DisputeActions.AsNoTracking().Where(x=>x.IdempotencyKey==request.IdempotencyKey).Select(x=>x.DisputeCaseId).SingleOrDefaultAsync(token);if(existing>0)return await BuildDisputeAsync(await db.DisputeCases.SingleAsync(x=>x.Id==existing,token),token);var row=await TransactionAsync(request.TransactionId,token);await using var transaction=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(token):null;var applicant=Reporter(request.ApplicantRoleCode,row);var item=await CreateDisputeEntityAsync(row,null,applicant,request.Subject,request.Description,request.IdempotencyKey,actor,token);await db.SaveChangesAsync(token);if(transaction is not null)await transaction.CommitAsync(token);return await BuildDisputeAsync(item,token);}

    public async Task<AdminDisputeDetail> ChangeDisputeStatusAsync(Guid id,ChangeDisputeStatusRequest request,Guid actorId,CancellationToken token)
    {var actor=await ActorAsync(actorId,token);var item=await DisputeAsync(id,token);if(await db.DisputeActions.AsNoTracking().AnyAsync(x=>x.IdempotencyKey==request.IdempotencyKey,token))return await BuildDisputeAsync(item,token);var target=Code(request.TargetStatusCode);if(!DisputeStates.Contains(target)||!ValidDisputeTransition(item.StatusCode,target))throw Error("DISPUTE_TRANSITION_INVALID",$"{item.StatusCode} 상태에서 {target} 상태로 변경할 수 없습니다.",409);if(target=="RESOLVED")throw Error("DISPUTE_RESOLUTION_REQUIRED","분쟁 해결은 최종 결과를 등록하여 처리해 주세요.",409);var now=DateTime.UtcNow;var from=item.StatusCode;item.StatusCode=target;if(target=="CLOSED")item.ClosedAt=now;item.LastActionAt=now;item.UpdatedAt=now;item.UpdatedByUserId=actor;db.DisputeActions.Add(NewDisputeAction(item,"STATUS_CHANGE",from,target,request.Note,null,actor,request.IdempotencyKey,now));Audit(actor,"DISPUTE_STATUS_CHANGED","DISPUTE_CASE",item.PublicId,JsonSerializer.Serialize(new{status=from}),JsonSerializer.Serialize(new{status=target}),request.Note,now);Outbox("DisputeCase",item.PublicId,$"DISPUTE_{target}",new{disputeId=item.PublicId,status=target},actor,now);await db.SaveChangesAsync(token);return await BuildDisputeAsync(item,token);}

    public async Task<AdminDisputeDetail> AssignDisputeAsync(Guid id,AssignDisputeRequest request,Guid actorId,CancellationToken token)
