    private IQueryable<TransactionRow> TransactionQuery(IQueryable<TransactionRecord> transactions)=>from tx in transactions join request in db.ServiceRequests.AsNoTracking()on tx.ServiceRequestId equals request.Id join category in db.ServiceCategories.AsNoTracking()on tx.CategoryId equals category.Id join middle in db.ServiceCategories.AsNoTracking()on category.ParentId equals middle.Id join major in db.ServiceCategories.AsNoTracking()on middle.ParentId equals major.Id join customer in db.CustomerProfiles.AsNoTracking()on tx.CustomerProfileId equals customer.Id join cu in db.Users.AsNoTracking()on customer.UserId equals cu.Id join provider in db.ProviderProfiles.AsNoTracking()on tx.ProviderProfileId equals provider.Id join pu in db.Users.AsNoTracking()on provider.UserId equals pu.Id join revision in db.QuoteRevisions.AsNoTracking()on tx.AcceptedQuoteRevisionId equals revision.Id select new TransactionRow(tx,request,category,middle,major,customer,cu,provider,pu,revision);
