    private static string Snap(object value)=>JsonSerializer.Serialize(value);private static string Code(string value)=>value.Trim().ToUpperInvariant();private static string? Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();private static void ValidateRequired(string? value,string message){if(Clean(value)is null)throw Error("REQUIRED_VALUE_MISSING",message);}private static void ValidatePage(int page,int size){if(page<1||size is<1 or>MaxPageSize)throw Error("PAGE_INVALID","페이지 값을 확인해 주세요.");}private static string? Mask(string? value)=>string.IsNullOrWhiteSpace(value)||value.Length<4?value:value[..Math.Min(3,value.Length-4)]+"-****-"+value[^4..];private static string AsNumber(Guid id)=>"AS-"+id.ToString("N")[..8].ToUpperInvariant();private static string DisputeNumber(Guid id)=>"분쟁-"+id.ToString("N")[..8].ToUpperInvariant();private static string TxNumber(Guid id)=>"거래-"+id.ToString("N")[..8].ToUpperInvariant();private static AfterServiceDisputeException Error(string code,string message,int status=400)=>new(code,message,status);
